class Solution {
public:
    int minCostII(vector<vector<int>>& costs) {
        if (costs.empty()) return 0;
        int prevMin1 = 0, prevMin2 = 0, prevIdx = -1;
        for (const auto& row : costs) {
            int currMin1 = INT_MAX, currMin2 = INT_MAX, currIdx = -1;
            for (size_t c = 0; c < row.size(); ++c) {
                int val = row[c] + (static_cast<int>(c) == prevIdx ? prevMin2 : prevMin1);
                if (val < currMin1) {
                    currMin2 = currMin1;
                    currMin1 = val;
                    currIdx = static_cast<int>(c);
                } else if (val < currMin2) {
                    currMin2 = val;
                }
            }
            prevMin1 = currMin1;
            prevMin2 = currMin2;
            prevIdx = currIdx;
        }
        return prevMin1;
    }
};

