    public int minCostII(int[][] costs) {
        if (costs.length == 0) return 0;
        int prevMin1 = 0, prevMin2 = 0, prevIdx = -1;
        for (int[] row : costs) {
            int currMin1 = Integer.MAX_VALUE, currMin2 = Integer.MAX_VALUE, currIdx = -1;
            for (int c = 0; c < row.length; c++) {
                int val = row[c] + (c == prevIdx ? prevMin2 : prevMin1);
